import{_ as a,o as l,a as n,b as t}from"./app.C41L12d5.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"设计与实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design"},{"text":"算子功能设计","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design.md","outlineHeaders":[{"level":2,"title":"前置理解：aclnn工程化算子开发方式由哪几部分组成","slug":"前置理解：aclnn工程化算子开发方式由哪几部分组成","link":"#前置理解：aclnn工程化算子开发方式由哪几部分组成"},{"level":2,"title":"围绕算子原型做功能设计","slug":"围绕算子原型做功能设计","link":"#围绕算子原型做功能设计"},{"level":2,"title":"围绕Host侧Tiling做功能设计","slug":"围绕Host侧Tiling做功能设计","link":"#围绕Host侧Tiling做功能设计"},{"level":2,"title":"围绕核函数（Kernel）侧实现做功能设计","slug":"围绕核函数（Kernel）侧实现做功能设计","link":"#围绕核函数（Kernel）侧实现做功能设计"},{"level":2,"title":"针对不同场景扩展核函数（Kernel）实现","slug":"针对不同场景扩展核函数（Kernel）实现","link":"#针对不同场景扩展核函数（Kernel）实现"},{"level":3,"title":"按数据类型扩展核函数（Kernel）实现","slug":"按数据类型扩展核函数（Kernel）实现","link":"#按数据类型扩展核函数（Kernel）实现"},{"level":3,"title":"按shape大小扩展核函数（Kernel）实现","slug":"按shape大小扩展核函数（Kernel）实现","link":"#按shape大小扩展核函数（Kernel）实现"},{"level":3,"title":"按运行时配置扩展核函数（Kernel）实现","slug":"按运行时配置扩展核函数（Kernel）实现","link":"#按运行时配置扩展核函数（Kernel）实现"},{"level":3,"title":"分支策略选择总结","slug":"分支策略选择总结","link":"#分支策略选择总结"},{"level":2,"title":"下一步","slug":"下一步","link":"#下一步"}],"lastUpdated":1787050286000}'),o={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design.md"};function i(d,e,r,c,s,p){return l(),n("div",null,[...e[0]||(e[0]=[t(`<div><article class="markdown-body"><h1>算子功能设计</h1><p>本文属于基础内容，介绍在编写自定义算子代码前需要完成的功能设计，包括将计算语义转换为工程实现，以及明确需要编写的工程文件。</p><p>本文以AddCustom算子作为示例。AddCustom的计算语义如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>z = x + y
</code></pre></div><p>本文只给出功能设计阶段需要明确的内容。具体接口和代码写法会在后续章节展开。</p><h2 id="前置理解：aclnn工程化算子开发方式由哪几部分组成">前置理解：aclnn工程化算子开发方式由哪几部分组成<a class="header-anchor" href="#前置理解：aclnn工程化算子开发方式由哪几部分组成">​</a></h2><p>一个aclnn自定义算子工程通常需要完成三类代码。</p><p>第一类代码：<strong>算子原型定义</strong>，声明算子的接口信息，包括输入、输出和属性，以及支持的dtype、format。</p><p>第二类代码：<strong>Host侧Tiling实现</strong>，在核函数（Kernel）执行前准备运行参数。核函数（Kernel）在AI Core上运行前，需要知道本次输入一共有多少数据、如何切核并启动多少个Block、每个Block内部如何继续切分、是否需要额外workspace，以及是否需要设置调度模式等launch配置。</p><p>第三类代码：<strong>核函数（Kernel）侧算子实现</strong>，在AI Core上执行的实际计算。核函数（Kernel）侧根据Tiling传入的参数，从GM搬运数据到Unified Buffer（UB），在UB上完成计算，再把结果写回GM。</p><p>本文的功能设计，就是在写这三类代码前，先确定每一类代码需要表达什么。</p><h2 id="围绕算子原型做功能设计">围绕算子原型做功能设计<a class="header-anchor" href="#围绕算子原型做功能设计">​</a></h2><p>算子原型设计从算子语义开始。算子语义描述算子接收什么数据、执行什么计算、输出什么结果。这个步骤决定OpDef中的输入输出声明，也决定Tiling和核函数（Kernel）需要围绕哪些数据设计。</p><p>AddCustom是逐元素加法算子。输入<code>x</code>和<code>y</code>在相同位置上的元素相加，结果写入输出<code>z</code>。每个元素的计算互相独立，适合按连续数据段切分到多个Block上并行处理。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>z[i] = x[i] + y[i]
</code></pre></div><p>根据这条语义，可以先确定算子对外暴露的原型边界。AddCustom对外暴露两个输入<code>x</code>、<code>y</code>和一个输出<code>z</code>。这三个Tensor已经可以完整表达<code>z = x + y</code>的计算语义，每次调用都需要提供，因此在原型边界上都属于必选参数。AddCustom没有额外属性，调用方只需要准备两个输入Tensor和一个输出Tensor。</p><p>如果算子带有标量、维度、阈值、开关等配置项，需要在功能设计阶段确定它们的承载方式。值较小且用于描述算子行为的配置项适合作为属性；需要按Tensor传入、参与动态图数据依赖或数据量较大的内容适合作为输入。属性识别和传递的完整示例请参考<a href="./tiling_data_attributes.html">通过TilingData传递属性信息</a>。</p><p>除此之外，还需要确定算子支持什么场景：</p><ul><li>数据类型和数据格式。</li><li>确定性：算子在相同输入下是否产生相同输出。</li></ul><p>将前两步确定的输入输出、dtype/format列表等合并，即得到完整的算子原型定义。完整的算子原型定义编写方法和API说明请参考<a href="./operator_prototype_definition.html">算子原型定义</a>。</p><p>完成算子原型设计后，功能设计可以继续拆解Host侧Tiling需要准备的运行参数，以及核函数（Kernel）侧如何完成实际计算。</p><h2 id="围绕Host侧Tiling做功能设计">围绕Host侧Tiling做功能设计<a class="header-anchor" href="#围绕Host侧Tiling做功能设计">​</a></h2><p>Host侧Tiling设计的重点，是确定核函数（Kernel）启动前需要准备哪些运行参数。Host侧Tiling负责把输入shape、属性等信息转换成核函数（Kernel）运行时需要的参数，包括切核策略、Block内切分、workspace大小、TilingKey和必要的调度模式等。AddCustom的核函数（Kernel）只需要知道总数据量和总数据的分块数量，因此TilingData设计为两个字段。</p><p>第一个字段是<code>totalLength</code>，表示本次计算的总元素数量。核函数（Kernel）侧会基于这个值计算每个Block处理的数据量。第二个字段是<code>tileNum</code>，表示样例中总数据的分块数量。核函数（Kernel）通过<code>totalLength / tileNum</code>计算单次处理的数据量，并与<code>numBlocks</code>共同确定每个Block的循环次数。</p><p>编写Tiling函数时，需要把这些设计结论转换成Host侧计算步骤。AddCustom的Tiling函数需要读取输入<code>x</code>的shape并计算<code>totalLength</code>，设置核函数（Kernel）启动使用的<code>numBlocks</code>，写入<code>tileNum</code>，并给出workspace大小；更复杂的算子还可能需要根据场景设置TilingKey或调度模式。</p><p>TilingData结构体、Tiling函数写法、workspace设置、<code>numBlocks</code>配置和相关launch参数会在<a href="./host_tiling_implementation.html">Host侧Tiling实现</a>章节详细展开。</p><h2 id="围绕核函数（Kernel）侧实现做功能设计">围绕核函数（Kernel）侧实现做功能设计<a class="header-anchor" href="#围绕核函数（Kernel）侧实现做功能设计">​</a></h2><p>核函数（Kernel）侧实现设计的重点，是确定AI Core上用什么计算API完成算子语义。AddCustom的语义是逐元素加法，对应到Ascend C基础API就是<code>Add</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>z[i] = x[i] + y[i]
        ↓
AscendC::Add(zLocal, xLocal, yLocal, length)
</code></pre></div><p>这里的<code>xLocal</code>和<code>yLocal</code>表示已经搬入UB的输入数据，<code>zLocal</code>表示UB中的输出数据。<code>length</code>表示本轮参与计算的元素个数，由核函数（Kernel）侧结合Host侧传入的Tiling信息确定。</p><p>从数据流上看，AddCustom采用基础的搬运、计算、写回流程：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>GM(x, y) -&gt; UB(xLocal, yLocal) -&gt; Add -&gt; UB(zLocal) -&gt; GM(z)
</code></pre></div><p>功能设计阶段只需要明确这条计算映射和基础数据流。核函数（Kernel）入口参数、TilingData读取等代码组织细节，会在<a href="./kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a>章节展开。</p><h2 id="针对不同场景扩展核函数（Kernel）实现">针对不同场景扩展核函数（Kernel）实现<a class="header-anchor" href="#针对不同场景扩展核函数（Kernel）实现">​</a></h2><p>完成基础核函数（Kernel）设计后，还需要判断当前实现能覆盖哪些场景。后续若需要支持更多数据类型、更大shape范围或运行时配置时，需要在基础实现上增加扩展策略。功能设计阶段需要先判断扩展维度和触发条件，后续再通过<a href="./multi_branch_strategy.html">多分支策略</a>说明TilingKey、核函数（Kernel）模板或差异化编译配置的具体写法。</p><h3 id="按数据类型扩展核函数（Kernel）实现">按数据类型扩展核函数（Kernel）实现<a class="header-anchor" href="#按数据类型扩展核函数（Kernel）实现">​</a></h3><p>当不同dtype的计算路径、精度要求或中间缓存不同，需要按数据类型评估核函数（Kernel）实现范围。以AddCustom为例，如果后续同时支持<code>float32</code>和<code>float16</code>，需要分别评估指令支持情况、数据搬运对齐、UB占用和Tile大小。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>float32: 元素占用空间较大，相同UB容量下单次可处理的元素数较少
float16: 元素占用空间较小，但仍需满足数据搬运和计算API的对齐要求
</code></pre></div><p>归约、累加或乘加等存在较长中间计算链的算子，可能需要使用<code>float32</code>保存中间结果以改善精度。但如果最终输出仍为<code>float16</code>，最终结果仍然必须处于<code>float16</code>的可表示范围内；升精度不能扩大最终输出的数据范围。</p><p>这种设计的重点，是在功能设计阶段提前识别dtype差异是否会改变核函数（Kernel）计算路径。后续如果需要根据dtype选择不同路径，可以在Host侧Tiling中设置对应标识，再由核函数（Kernel）侧选择匹配实现。</p><h3 id="按shape大小扩展核函数（Kernel）实现">按shape大小扩展核函数（Kernel）实现<a class="header-anchor" href="#按shape大小扩展核函数（Kernel）实现">​</a></h3><p>当数据量差异较大时，不同shape适合的切分策略也可能不同。小shape可能一次搬入UB完成计算，大shape通常需要按Block和Tile分块循环处理。</p><p>以AddCustom为例，可以在功能设计阶段先给出shape分界思路：总元素数较小时使用较少Tile，减少循环开销；总元素数较大时增加Tile数量，让每个Block按多轮搬运、计算和写回处理数据。具体阈值需要结合UB容量、对齐要求、尾块处理方式和性能验证结果确定。配套基础样例的输入shape为<code>[8, 2048]</code>，固定使用8个Block，<code>tileNum</code>取8。此时每个Block处理2048个元素，单次也处理2048个元素，因此每个Block只循环1次。该样例只覆盖固定规格；扩展shape范围时需要重新计算切分参数，并补充不能整除时的尾核、尾Tile处理。</p><h3 id="按运行时配置扩展核函数（Kernel）实现">按运行时配置扩展核函数（Kernel）实现<a class="header-anchor" href="#按运行时配置扩展核函数（Kernel）实现">​</a></h3><p>运行时配置也可能影响核函数（Kernel）实现路径。典型场景是确定性配置：相同输入下要求输出完全稳定时，核函数（Kernel）需要固定计算顺序；追求性能时，某些归约类算子可能采用更灵活的并行顺序。</p><p>AddCustom是逐元素加法，元素之间没有依赖关系，基础实现采用固定的数据分片和计算顺序，属于确定性实现。对于归约、排序等存在跨元素关系的算子，需要在功能设计阶段记录确定性要求，并判断是否需要准备不同核函数（Kernel）路径。</p><h3 id="分支策略选择总结">分支策略选择总结<a class="header-anchor" href="#分支策略选择总结">​</a></h3><p>关于TilingKey和核函数（Kernel）模板的选择准则，请参考<a href="./multi_branch_strategy.html">多分支策略</a>。</p><h2 id="下一步">下一步<a class="header-anchor" href="#下一步">​</a></h2><ul><li><a href="./operator_prototype_definition.html">算子原型定义</a>：输入、输出、属性、dtype/format。</li><li><a href="./host_tiling_implementation.html">Host侧Tiling实现</a>：TilingData定义和Tiling函数编写。</li><li><a href="./kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a>：数据搬运、计算接口和核函数（Kernel）编程流程。</li><li><a href="./multi_branch_strategy.html">多分支策略</a>：TilingKey和不同核函数（Kernel）分支的选择方法。</li><li><a href="./tiling_data_attributes.html">通过TilingData传递属性信息</a>：属性读取和传递介绍。</li></ul></article></div>`,1)])])}const m=a(o,[["render",i]]);export{g as __pageData,m as default};
